require_once __DIR__.'/../includes/layout.php';require_once __DIR__.'/../includes/auth.php';
$admin=require_admin();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT c.*,rd.identity_status rescued_identity,rd.rescue_location,rd.estimated_age_min r_age_min,rd.estimated_age_max r_age_max,rd.distinguishing_marks r_marks,dd.* FROM cases c LEFT JOIN rescued_person_details rd ON rd.case_id=c.id LEFT JOIN deceased_details dd ON dd.case_id=c.id WHERE c.id=? AND c.deleted_at IS NULL');$q->execute([$id]);$case=$q->fetch();if(!$case||!in_array($case['type'],['rescued','deceased'],true)){http_response_code(404);exit('Reconciliation is available for rescued/deceased records.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 if($action==='run_match'&&can_manage_dvi($admin['role'])){$n=run_case_reconciliation($id,$admin['id']);audit($admin['id'],'run_reconciliation',$id,'Generated/updated '.$n.' candidates');flash('success','Reconciliation completed. '.$n.' candidate record(s) scored.');}
 elseif($action==='review_match'&&can_manage_dvi($admin['role'])){$mid=(int)($_POST['match_id']??0);$st=$_POST['match_status']??'reviewed';if(!in_array($st,['reviewed','rejected','confirmed'],true))$st='reviewed';$m=db()->prepare('SELECT * FROM case_matches WHERE id=? AND source_case_id=?');$m->execute([$mid,$id]);$match=$m->fetch();if($match){if($st==='confirmed'&&$case['type']==='deceased'){$st='reviewed';flash('warning','A deceased candidate link cannot be confirmed from similarity. Submit the separate identification approval request with competent forensic/official basis.');}db()->prepare('UPDATE case_matches SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=?')->execute([$st,$admin['id'],$mid]);audit($admin['id'],'review_case_match',$id,'Match '.$mid.' => '.$st);}}
 elseif($action==='request_identification'&&$case['type']==='deceased'&&can_manage_dvi($admin['role'])){$source=(string)($_POST['identity_source']??'');$basis=trim((string)($_POST['identification_basis']??''));[$srcType,$srcId]=array_pad(explode(':',$source,2),2,'');$srcId=(int)$srcId;$missing=null;$familyReq=null;if($srcType==='case'){$ms=db()->prepare("SELECT * FROM cases WHERE id=? AND type='missing' AND deleted_at IS NULL");$ms->execute([$srcId]);$missing=$ms->fetch();}elseif($srcType==='family'){$fq=db()->prepare('SELECT * FROM family_match_requests WHERE id=? AND target_case_id=?');$fq->execute([$srcId,$id]);$familyReq=$fq->fetch();}if(!$missing&&!$familyReq)flash('danger','Select a valid missing-person candidate or family match request.');elseif($basis==='')flash('danger','Identification basis is required. State the fingerprint/DNA/dental or other competent official evidence.');else{$pending=db()->prepare("SELECT COUNT(*) FROM identification_approval_requests WHERE case_id=? AND status='pending'");$pending->execute([$id]);if((int)$pending->fetchColumn())flash('warning','An identification approval request is already pending.');else{$proposedName=$missing?$missing['name']:$familyReq['missing_person_name'];$missingCaseId=$missing?$missing['id']:null;$familyId=$familyReq?$familyReq['id']:null;db()->prepare("INSERT INTO identification_approval_requests(case_id,proposed_missing_case_id,family_match_request_id,proposed_identity_name,identification_basis,requested_by) VALUES (?,?,?,?,?,?)")->execute([$id,$missingCaseId,$familyId,$proposedName,$basis,$admin['id']]);db()->prepare("UPDATE cases SET status='identification_review',status_updated_at=NOW(),status_updated_by=? WHERE id=?")->execute([$admin['id'],$id]);db()->prepare("UPDATE deceased_details SET identity_status='under_review' WHERE case_id=?")->execute([$id]);audit($admin['id'],'request_identification_approval',$id,($missing?$missing['case_code']:'family:'.$familyReq['request_code']).' | '.$basis);flash('success','Identification approval requested. A different Approver/Superadmin must review it.');}}}
 elseif($action==='review_identification'&&$case['type']==='deceased'&&can_approve_identification($admin['role'])){$rid=(int)($_POST['request_id']??0);$decision=$_POST['decision']??'';$notes=trim((string)($_POST['review_notes']??''));$r=db()->prepare("SELECT r.*,m.name missing_name,m.age missing_age,m.from_location missing_address,f.missing_person_name fr_name,f.missing_person_age fr_age,f.missing_person_address fr_address FROM identification_approval_requests r LEFT JOIN cases m ON m.id=r.proposed_missing_case_id LEFT JOIN family_match_requests f ON f.id=r.family_match_request_id WHERE r.id=? AND r.case_id=? AND r.status='pending'");$r->execute([$rid,$id]);$req=$r->fetch();if(!$req)flash('danger','Pending identification request not found.');elseif((int)$req['requested_by']===(int)$admin['id'])flash('danger','Separation of duties: the person who requested identification cannot approve the same request.');elseif(!in_array($decision,['approved','rejected'],true))flash('danger','Choose approve or reject.');else{$finalName=$req['missing_name']??$req['fr_name'];$finalAge=$req['missing_age']??$req['fr_age'];$finalAddress=$req['missing_address']??$req['fr_address'];db()->beginTransaction();try{db()->prepare('UPDATE identification_approval_requests SET status=?,reviewed_by=?,reviewed_at=NOW(),review_notes=? WHERE id=?')->execute([$decision,$admin['id'],$notes,$rid]);if($decision==='approved'){$basis=$req['identification_basis'];db()->prepare("UPDATE deceased_details SET identity_status='confirmed',official_identification_method=?,official_identity_name=?,official_identity_age=?,official_identity_address=?,identification_approved_by=?,identification_approved_at=NOW() WHERE case_id=?")->execute([$basis,$finalName,$finalAge,$finalAddress,$admin['id'],$id]);db()->prepare("UPDATE cases SET name=?,age=?,from_location=?,status='forensic_confirmed',status_updated_at=NOW(),status_updated_by=? WHERE id=?")->execute([$finalName,$finalAge,$finalAddress,$admin['id'],$id]);if($req['proposed_missing_case_id'])db()->prepare("UPDATE case_matches SET status='confirmed',reviewed_by=?,reviewed_at=NOW() WHERE source_case_id=? AND candidate_case_id=?")->execute([$admin['id'],$id,$req['proposed_missing_case_id']]);if($req['family_match_request_id'])db()->prepare("UPDATE family_match_requests SET status='verified',reviewed_by=?,reviewed_at=NOW(),review_notes=CONCAT(COALESCE(review_notes,''),?) WHERE id=?")->execute([$admin['id'],"\nVerified through formal identification approval on ".date('Y-m-d H:i'),$req['family_match_request_id']]);db()->prepare("INSERT INTO case_updates(case_id,admin_id,update_category,status_after,condition_after,note,public_visible) VALUES (?,?,'status','forensic_confirmed','deceased','Identity formally approved. Public identity remains restricted unless separately released.',1)")->execute([$id,$admin['id']]);}else{db()->prepare("UPDATE deceased_details SET identity_status='unidentified' WHERE case_id=?")->execute([$id]);db()->prepare("UPDATE cases SET status='under_review',status_updated_at=NOW(),status_updated_by=? WHERE id=?")->execute([$admin['id'],$id]);}db()->commit();audit($admin['id'],'review_identification',$id,$decision.' | '.$notes);flash('success','Identification review saved: '.$decision);}catch(Throwable $e){db()->rollBack();flash('danger',$e->getMessage());}}}
 elseif($action==='release_identity'&&$case['type']==='deceased'&&can_approve_identification($admin['role'])){$v=!empty($_POST['public_identity_release'])?1:0;db()->prepare('UPDATE deceased_details SET public_identity_release=? WHERE case_id=?')->execute([$v,$id]);audit($admin['id'],'set_public_identity_release',$id,$v?'released':'restricted');flash('success',$v?'Official identity may now appear in public search.':'Official identity is restricted from public search.');}
 redirect(base_url('admin/reconciliation.php?id='.$id));
}
$ms=db()->prepare('SELECT cm.*,m.case_code candidate_code,m.name candidate_name,m.age candidate_age,m.gender candidate_gender,m.from_location,m.last_seen_address,m.last_contacted_bs,m.photo_url,a.name reviewed_name FROM case_matches cm JOIN cases m ON m.id=cm.candidate_case_id LEFT JOIN admins a ON a.id=cm.reviewed_by WHERE cm.source_case_id=? ORDER BY cm.match_score DESC,cm.id DESC');$ms->execute([$id]);$matches=$ms->fetchAll();
$fr=db()->prepare('SELECT * FROM family_match_requests WHERE target_case_id=? ORDER BY created_at DESC');$fr->execute([$id]);$familyRequests=$fr->fetchAll();
$ia=db()->prepare('SELECT r.*,rq.name requested_name,rv.name reviewed_name,m.case_code missing_code,f.request_code family_request_code FROM identification_approval_requests r JOIN admins rq ON rq.id=r.requested_by LEFT JOIN admins rv ON rv.id=r.reviewed_by LEFT JOIN cases m ON m.id=r.proposed_missing_case_id LEFT JOIN family_match_requests f ON f.id=r.family_match_request_id WHERE r.case_id=? ORDER BY r.id DESC');$ia->execute([$id]);$identReqs=$ia->fetchAll();
$matchStatusNp=['pending'=>'बाँकी','reviewed'=>'समीक्षा गरिएको','rejected'=>'अस्वीकृत','confirmed'=>'पुष्टि भएको'];
$reqStatusNp=['pending'=>'बाँकी','approved'=>'स्वीकृत','rejected'=>'अस्वीकृत'];
$famStatusNp=['submitted'=>'पेश गरिएको','under_review'=>'समीक्षामा','possible_match'=>'सम्भावित मिलान','verified'=>'प्रमाणित','rejected'=>'अस्वीकृत','closed'=>'बन्द'];
