<div class="table-wrap"><table><thead><tr><th><?=render_lang('Score','स्कोर')?></th><th><?=render_lang('Missing Case','बेपत्ता केस')?></th><th><?=render_lang('Person','व्यक्ति')?></th><th><?=render_lang('Last Seen','अन्तिम देखिएको')?></th><th><?=render_lang('Reasons','कारण')?></th><th><?=render_lang('Review','समीक्षा')?></th></tr></thead><tbody><?php foreach($matches as $m):?><tr><td><strong><?=e(number_format((float)$m['match_score'],0))?>%</strong></td><td><?=e($m['candidate_code'])?></td><td><b><?=e($m['candidate_name'])?></b><br><span class="small"><?=render_lang('Age','उमेर')?> <?=e($m['candidate_age']??'?')?> · <?=e($m['candidate_gender'])?></span></td><td><?=e($m['last_seen_address']?:$m['from_location'])?><br><span class="small"><?=e($m['last_contacted_bs'])?></span></td><td><?php foreach(json_decode($m['reasons_json']??'[]',true)?:[] as $reason):?><span class="match-reason"><?=e($reason)?></span><?php endforeach;?></td><td><span class="status"><?=render_lang(ucwords($m['status']),$matchStatusNp[$m['status']]??$m['status'])?></span><?php if(can_manage_dvi($admin['role'])):?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="review_match"><input type="hidden" name="match_id" value="<?=$m['id']?>"><select name="match_status"><option value="reviewed">Reviewed / समीक्षा गरियो</option><option value="rejected">Reject / अस्वीकार</option><?php if($case['type']==='rescued'):?><option value="confirmed">Confirm candidate link / पुष्टि गर्नुहोस्</option><?php endif;?></select><button class="btn btn-sm btn-secondary"><?=render_lang('Save','सुरक्षित')?></button></form><?php endif;?></td></tr><?php endforeach;?><?php if(!$matches):?><tr><td colspan="6"><?=render_lang('No candidate scores yet. Run matching.','अहिलेसम्म कुनै सम्भावित स्कोर छैन। मिलान चलाउनुहोस्।')?></td></tr><?php endif;?></tbody></table></div></div>

